sys_sg_write_back_action_item.execution_script:
var qty = parseFloat(inputs.production_quantity) || 0;
if (qty <= 0) { output.error = "Quantity must be a positive number."; }
else {
  var produced = parseFloat(current.getValue("quantity_produced")) || 0;
  var remaining = parseFloat(current.getValue("quantity_remaining")) || 0;
  if (qty > remaining) { output.error = "Quantity (" + qty + ") exceeds remaining (" + remaining + ")."; }
  else {
    current.setValue("quantity_produced", (produced + qty).toString());
    current.setValue("quantity_remaining", (remaining - qty).toString());
    current.update();
    output.success = true;
    output.message = "Recorded " + qty + " units. Produced: " + (produced + qty) + ", Remaining: " + (remaining - qty);
  }
}
